import React, { useRef } from 'react';
import { X, CheckCircle, AlertCircle, Plus, ImagePlus } from 'lucide-react';

const PHOTO_REFS = {
  perfil: "data:image/jpeg;base64,",
  cockpit: "data:image/jpeg;base64,",
  cambio: "data:image/jpeg;base64,",
  suspensao: "data:image/jpeg;base64,",
  shock: "data:image/jpeg;base64,",
  detalhes: "data:image/jpeg;base64,",
};

const PHOTO_GUIDES = [
  {
    id: 'perfil',
    label: 'Bike de perfil',
    required: true,
    tip: 'Lado da relação (câmbio e cassete visíveis). Celular HORIZONTAL, altura do guidão. Fundo neutro.',
    checks: ['Celular deitado (horizontal)', 'Fundo neutro — parede branca/cinza', 'Pedivela para frente', 'Lado da relação'],
    ref: 'perfil',
  },
  {
    id: 'cockpit',
    label: 'Cockpit (guidão + mesa)',
    required: true,
    tip: 'Guidão, mesa e manetes de freio bem visíveis.',
    checks: ['Guidão e mesa visíveis', 'Manetes de freio aparecendo', 'Foto nítida e iluminada'],
    ref: 'cockpit',
  },
  {
    id: 'cambio',
    label: 'Câmbio e cassete',
    required: true,
    tip: 'Câmbio aberto em marcha intermediária. Cassete e pedivela bem visíveis.',
    checks: ['Câmbio aberto (marcha intermediária)', 'Cassete visível', 'Componentes limpos'],
    ref: 'cambio',
  },
  {
    id: 'suspensao',
    label: 'Suspensão (garfo)',
    required: true,
    tip: 'Estria do garfo e pneu dianteiro. Foto limpa e iluminada.',
    checks: ['Estria do garfo visível', 'Pneu dianteiro aparecendo', 'Freio dianteiro visível'],
    ref: 'suspensao',
  },
  {
    id: 'shock',
    label: 'Amortecedor / Quadro traseiro',
    required: true,
    tip: 'Full suspension: foto do amortecedor. Hardtail: foto do quadro traseiro.',
    checks: ['Amortecedor ou quadro traseiro', 'Linkagem visível se full', 'Foto nítida'],
    ref: 'shock',
  },
  {
    id: 'detalhes',
    label: 'Detalhes / danos',
    required: false,
    tip: 'Amassados, arranhões ou qualquer detalhe que o comprador deve saber.',
    checks: ['Mostre riscos ou amassados', 'Honestidade gera confiança', 'Zoom nos detalhes'],
    ref: 'detalhes',
  },
];

export default function Step4({ data, onChange }) {
  const inputRefs = useRef({});
  const globalRef = useRef();
  const photos = data.photos || [];

  const handleFiles = (e, slotIndex) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;
    if (slotIndex !== undefined) {
      const updated = [...photos];
      files.forEach((file, i) => { updated[slotIndex + i] = file; });
      onChange({ ...data, photos: updated.slice(0, 12) });
    } else {
      onChange({ ...data, photos: [...photos, ...files].slice(0, 12) });
    }
    e.target.value = '';
  };

  const removePhoto = (index) => {
    onChange({ ...data, photos: photos.filter((_, i) => i !== index) });
  };

  const getRef = (id) => {
    if (!inputRefs.current[id]) inputRefs.current[id] = React.createRef();
    return inputRefs.current[id];
  };

  return (
    <div className="step-content">
      <div className="step-header">
        <div className="step-icon" style={{fontSize:'22px'}}>📸</div>
        <div>
          <h2>Fotos da bike</h2>
          <p>Mínimo 5 fotos · Mais fotos = venda mais rápida</p>
        </div>
      </div>

      <div className="tips-banner">
        <div className="tips-banner-row"><CheckCircle size={14} className="tip-icon-ok" /><span>Bike <strong>limpa e seca</strong></span></div>
        <div className="tips-banner-row"><CheckCircle size={14} className="tip-icon-ok" /><span>Fundo <strong>neutro</strong> — parede branca ou cinza</span></div>
        <div className="tips-banner-row"><CheckCircle size={14} className="tip-icon-ok" /><span>Celular <strong>deitado</strong> (horizontal)</span></div>
        <div className="tips-banner-row"><CheckCircle size={14} className="tip-icon-ok" /><span>Pedivela <strong>horizontal, para frente</strong></span></div>
      </div>

      <div className="photo-cards-grid">
        {PHOTO_GUIDES.map((guide, idx) => {
          const photo = photos[idx];
          const isDone = !!photo;
          return (
            <div key={guide.id} className={`photo-card ${isDone ? 'photo-card-done' : ''}`}>
              <input
                ref={getRef(guide.id)}
                type="file"
                accept="image/*"
                onChange={(e) => handleFiles(e, idx)}
                style={{ display: 'none' }}
              />
              <div className="photo-card-visual" onClick={() => getRef(guide.id).current.click()}>
                {isDone ? (
                  <>
                    <img src={URL.createObjectURL(photo)} alt={guide.label} className="photo-card-preview" />
                    <div className="photo-card-done-overlay"><CheckCircle size={28} color="#0c0c0c" /></div>
                  </>
                ) : (
                  <>
                    <img src={PHOTO_REFS[guide.ref]} alt={guide.label} className="photo-card-preview photo-card-ref" />
                    <div className="photo-card-add-btn"><Plus size={20} /></div>
                  </>
                )}
              </div>
              <div className="photo-card-info">
                <div className="photo-card-label-row">
                  <span className="photo-card-label">{guide.label}</span>
                  {guide.required ? <span className="badge-required">obrigatória</span> : <span className="badge-optional">opcional</span>}
                </div>
                <p className="photo-card-tip">{guide.tip}</p>
                <div className="photo-card-checks">
                  {guide.checks.map((c, i) => (
                    <span key={i} className="photo-check-item">
                      <CheckCircle size={10} className="tip-icon-ok" /> {c}
                    </span>
                  ))}
                </div>
                {isDone && (
                  <button type="button" className="photo-card-remove" onClick={() => removePhoto(idx)}>
                    <X size={12} /> Remover
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>

      <div className="upload-section" style={{marginTop: '8px'}}>
        <input ref={globalRef} type="file" accept="image/*" multiple onChange={(e) => handleFiles(e)} style={{ display: 'none' }} />
        <button type="button" className="upload-btn" onClick={() => globalRef.current.click()}>
          <ImagePlus size={18} />
          {photos.length === 0 ? 'Adicionar fotos' : `Adicionar mais (${photos.length} foto${photos.length > 1 ? 's' : ''})`}
        </button>
        <p className="upload-hint">Toque para abrir galeria ou câmera</p>
      </div>

      <div className="photo-progress">
        <div className="photo-progress-bar">
          <div className="photo-progress-fill" style={{ width: `${Math.min((photos.length / 5) * 100, 100)}%` }} />
        </div>
        <span className={photos.length >= 5 ? 'progress-ok' : 'progress-warn'}>
          {photos.length >= 5 ? `✓ ${photos.length} fotos — ótimo!` : `${photos.length}/5 fotos mínimas`}
        </span>
      </div>
    </div>
  );
}
